-- 8.2 Periodic batch closing processor for closing rounds
CREATE OR REPLACE FUNCTION public._process_closing_tester_bonus_rounds()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
    v_round record;
    v_closed_count integer := 0;
begin
    for v_round in
        select r.id, r.campaign_id, c.status as camp_status, c.paused_reason as camp_paused_reason
        from public.campaign_tester_bonus_rounds r
        left join public.campaigns c on c.id = r.campaign_id
        where r.status = 'closing'
        order by r.created_at
        for update of r skip locked
    loop
        if not exists (
            select 1 from public.tester_reports
            where tester_bonus_round_id = v_round.id
              and status = 'pending'
        ) then
            perform public._close_and_refund_tester_bonus_round(v_round.id, 'closing_batch_settled');
            v_closed_count := v_closed_count + 1;

            if v_round.camp_status = 'closed' and v_round.camp_paused_reason = 'admin_deletion_pending' then
                delete from public.campaigns where id = v_round.campaign_id;
            end if;
        end if;
    end loop;

    return v_closed_count;
end;
$function$;

